import{c as n,$ as i,Q as t,j as s,m as a,h as d,ax as r,n as c,o as l,S as p}from"./chunks/framework.DCQwiej8.js";const E=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline/guide/recipes/index.md","filePath":"pipeline/guide/recipes/index.md","lastUpdated":1783588917000}'),u={name:"pipeline/guide/recipes/index.md"};function h(m,e,g,v,f,A){const o=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Several ways to plug into <code>cds-data-pipeline</code>, ordered by how much code you write. Each recipe is a scenario-driven walkthrough — config, code, and the resulting run behaviour — anchored on a single plugin entry point.</p><table tabindex="0"><thead><tr><th>Plugin entry point</th><th>When to pick it</th><th>Recipe</th></tr></thead><tbody><tr><td><strong>Built-in adapters, no code</strong> — source is OData / REST / CQN, target is local DB or remote OData</td><td>Most common case. Row-preserving copy, derived snapshots, move-to-OData.</td><td><a href="./built-in-replicate.html">Built-in replicate</a> · <a href="./built-in-materialize.html">Built-in materialize</a></td></tr><tr><td><strong>Multi-source fan-in</strong> — same logical entity from N backends into one target</td><td>DEV / QA / PROD consolidation, cross-region replication into a single reporting table. Sibling pipelines + <code>source.origin</code> stamp.</td><td><a href="./multi-source.html">Multi-source fan-in</a></td></tr><tr><td><strong>Custom source adapter</strong> — source transport is not OData / REST / CQN</td><td>Reading from CSV, files, proprietary HTTP APIs, message buses, anything else.</td><td><a href="./custom-source-adapter.html">Custom source adapter</a></td></tr><tr><td><strong>Custom target adapter</strong> — target is not the local DB and not an OData service</td><td>Forwarding to reporting services, message buses, custom HTTP APIs. Reusable across pipelines.</td><td><a href="./custom-target-adapter.html">Custom target adapter</a></td></tr><tr><td><strong><code>PIPELINE.*</code> event hooks</strong> — minimal-effort customization of any phase</td><td>Filter, enrich, normalize, forward, react to completion. <code>before</code> / <code>on</code> / <code>after</code> on <code>PIPELINE.START / READ / MAP_BATCH / WRITE_BATCH / DONE</code> in classic CAP style.</td><td><a href="./event-hooks.html">Event hooks</a></td></tr><tr><td><strong>Event-driven micro-runs</strong> — batch pipeline + messaging notifications on the same name</td><td>Key or payload upserts/deletes via <code>executeEvent</code>; batch watermark preserved. CAP messaging / CloudEvents handlers call <code>execute</code> with nested <code>event</code>.</td><td><a href="./event-driven-runs.html">Event-driven runs</a></td></tr><tr><td><strong>External scheduler (JSS / CronJob)</strong> — drive pipelines from outside the CAP app</td><td>Centralized BTP-native cron, corporate scheduling policies, org-level run observability. Omit <code>schedule</code>; call <code>POST /pipeline/execute</code>.</td><td><a href="./external-scheduling-jss.html">External scheduling (JSS)</a></td></tr><tr><td><strong>In-process queued scheduler</strong> — persistent schedule where only one app instance runs the tick</td><td>Scaled deployments (&gt;1 app instance) that want persistence, retry, and cross-instance safety without an external service. <code>schedule: { every, engine: &#39;queued&#39; }</code>.</td><td><a href="./internal-scheduling-queued.html">Internal scheduling (queued)</a></td></tr></tbody></table><h2 id="decision-tree" tabindex="-1">Decision tree <a class="header-anchor" href="#decision-tree" aria-label="Permalink to &quot;Decision tree&quot;">​</a></h2>',4)),(t(),d(p,null,{default:r(()=>[l(o,{id:"mermaid-114",class:"mermaid",graph:"flowchart%20TD%0A%20%20start%5BNew%20pipeline%5D%20--%3E%20src%7B%22Source%20kind%3F%22%7D%0A%20%20src%20--%3E%7C%22OData%20%2F%20REST%20%2F%20CQN%22%7C%20srcBuiltin%5BUse%20built-in%20source%20adapter%5D%0A%20%20src%20--%3E%7C%22Anything%20else%22%7C%20srcCustom%5BWrite%20custom%20source%20adapter%5D%0A%0A%20%20srcBuiltin%20--%3E%20tgt%7B%22Target%20kind%3F%22%7D%0A%20%20srcCustom%20--%3E%20tgt%0A%0A%20%20tgt%20--%3E%7C%22Local%20DB%20('db'%20or%20unset)%22%7C%20tgtDb%5BDbTargetAdapter%20-%20no%20code%5D%0A%20%20tgt%20--%3E%7C%22OData%20%2F%20OData%20V2%22%7C%20tgtOdata%5BODataTargetAdapter%20-%20no%20code%5D%0A%20%20tgt%20--%3E%7C%22Reusable%20non-db%20non-OData%22%7C%20tgtCustom%5BWrite%20custom%20target%20adapter%5D%0A%20%20tgt%20--%3E%7C%22One-off%20forwarding%22%7C%20tgtHook%5BLayer%20PIPELINE.*%20hooks%5D%0A%0A%20%20tgtDb%20--%3E%20shape%7B%22Read%20shape%3F%22%7D%0A%20%20shape%20--%3E%7C%22Entity-shape%22%7C%20replicate%5B%22Recipe%3A%20Built-in%20replicate%22%5D%0A%20%20shape%20--%3E%7C%22Query-shape%20(source.query)%22%7C%20materialize%5B%22Recipe%3A%20Built-in%20materialize%22%5D%0A%0A%20%20tgtOdata%20--%3E%20replicate%0A%20%20tgtCustom%20--%3E%20customTgt%5B%22Recipe%3A%20Custom%20target%20adapter%22%5D%0A%20%20tgtHook%20--%3E%20hookRecipe%5B%22Recipe%3A%20Event%20hooks%22%5D%0A%20%20srcCustom%20--%3E%20customSrc%5B%22Recipe%3A%20Custom%20source%20adapter%22%5D%0A%0A%20%20replicate%20--%3E%20eventDriven%7B%22Also%20need%20real-time%20notifications%3F%22%7D%0A%20%20eventDriven%20--%3E%7C%22Yes%22%7C%20eventRecipe%5B%22Recipe%3A%20Event-driven%20runs%22%5D%0A%20%20eventDriven%20--%3E%7C%22No%22%7C%20done%5BDone%5D%0A%20%20eventRecipe%20--%3E%20done%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="use-case-labels" tabindex="-1">Use-case labels <a class="header-anchor" href="#use-case-labels" aria-label="Permalink to &quot;Use-case labels&quot;">​</a></h2><p>The terms <em>replicate</em>, <em>materialize</em>, and <em>move-to-service</em> appear in the recipes as labels for common <em>combinations</em> of read shape and target destination. They are documentation vocabulary — not a field on <code>addPipeline(...)</code> and not a column on the tracker. See <a href="./../concepts/inference.html">Concepts → Inference rules</a>.</p><table tabindex="0"><thead><tr><th>Label</th><th>What it maps to</th><th>Recipe</th></tr></thead><tbody><tr><td><strong>Replicate</strong></td><td>Entity-shape read, DB target (row-preserving)</td><td><a href="./built-in-replicate.html">Built-in replicate</a></td></tr><tr><td><strong>Materialize</strong></td><td>Query-shape read, DB target (snapshot)</td><td><a href="./built-in-materialize.html">Built-in materialize</a></td></tr><tr><td><strong>Move-to-service</strong></td><td>Entity-shape read, non-DB target</td><td><a href="./built-in-replicate.html#to-a-remote-odata-target">Built-in replicate → OData target</a> · <a href="./custom-target-adapter.html">Custom target adapter</a> · <a href="./event-hooks.html">Event hooks</a></td></tr><tr><td><strong>Event-driven</strong></td><td>Batch pipeline + messaging micro-runs on the same name</td><td><a href="./event-driven-runs.html">Event-driven runs</a></td></tr></tbody></table>',3))])}const b=n(u,[["render",h]]);export{E as __pageData,b as default};
